SELECT @@session.time_zone AS session_tz, @@global.time_zone AS global_tz, @@system_time_zone AS system_tz, NOW(6) AS now_session, UTC_TIMESTAMP(6) AS now_utc, TIMESTAMPDIFF(MINUTE, UTC_TIMESTAMP(), NOW()) AS offset_minutes, (SELECT candle_open_time FROM trade_signal WHERE id=150942) AS sig150942_open_rendered, (SELECT execution_price_observed_at FROM wallet_trade WHERE id=195) AS wt195_observed_rendered;